function platformHttp($path,$method='GET',$body='',array$headers=[]){global$base;$r=file_get_contents($base.$path,false,stream_context_create(['http'=>['method'=>$method,'content'=>$body,'header'=>implode("\r\n",$headers),'ignore_errors'=>true,'timeout'=>10]]));$h=$http_response_header??[];preg_match('/\s(\d{3})\s/',$h[0]??'',$m);return['status'=>(int)($m[1]??0),'body'=>$r,'headers'=>$h];}
function platformCookie($r){foreach($r['headers']as$h)if(stripos($h,'Set-Cookie:')===0)return explode(';',trim(substr($h,11)))[0];throw new RuntimeException('Missing session cookie');}
function platformJson($data,$headers=[]){global$base;return platformHttp('/api/platform_settings.php','POST',json_encode($data),array_merge(['Origin: '.$base,'Content-Type: application/json'],$headers));}
